window.START_COURSES.find(c=>c.id==="formacao-freudiana").modules.push({"id":"freud_m06","title":"Freud [1924–1931]","description":"Transformações da teoria da angústia, cultura, formação e sexualidade. Critérios cronológicos preservam o agrupamento do índice de origem.","lessons":[{"id":"freud_a125","title":"O Problema Econômico do Masoquismo","minutes":18,"hook":"Qual é o problema teórico por trás de “masoquismo erógeno, feminino e moral” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “masoquismo erógeno, feminino e moral”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Freud relaciona formas de masoquismo à teoria das pulsões e ao problema do sofrimento. O termo faz parte de categorias históricas e não autoriza confundir práticas consensuais adultas com transtornos, nem presumir que qualquer vítima 'gosta de sofrer'. A dimensão econômica é um modelo de funcionamento pulsional, não cálculo de intensidade física."},{"title":"Entenda o conceito: Masoquismo erógeno, feminino e moral","body":"Freud propõe distinções para explicar relações entre prazer, sofrimento e culpa. Sua categoria de 'masoquismo feminino' reflete pressupostos de gênero controversos e não descreve essência da feminilidade. Nenhuma teoria psicanalítica justifica responsabilizar pessoas por violências sofridas.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"A obra depende da teoria de pulsão de morte de 1920 e antecipa discussões sobre culpa e supereu.\n\nNota ética: não inferir consentimento ao sofrimento nem patologizar práticas consensuais."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “masoquismo erógeno, feminino e moral”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Uma pessoa permanece em relação abusiva por medo, dependência econômica ou risco de violência. Dizer que ela 'quer sofrer' seria uma forma grave de culpabilização.\n\nAgora retome o foco desta aula: masoquismo erógeno, feminino e moral. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Masoquismo moral","desc":"Construção freudiana referente a relações entre culpa e sofrimento."},{"term":"Modelo econômico","desc":"Dimensão metapsicológica de intensidades e investimentos pulsionais."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “masoquismo erógeno, feminino e moral” nesta obra?","options":["Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1924, distinguindo hipótese, exemplos e limites da interpretação."],"correct":2,"feedback":"O tópico “Masoquismo erógeno, feminino e moral” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1924) — O Problema Econômico do Masoquismo. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a126","title":"Freud - Um Estudo Autobiográfico #1","minutes":18,"hook":"Qual é o problema teórico por trás de “a narrativa de origem de freud” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “a narrativa de origem de freud”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Freud apresenta sua trajetória de pesquisa, as origens da técnica e o desenvolvimento da psicanálise. A autobiografia é fonte primária valiosa, mas também uma apresentação seletiva de si próprio; convém compará-la com correspondência, textos datados e historiografia."},{"title":"Entenda o conceito: A narrativa de origem de Freud","body":"O autor reconstrói a passagem da neurologia e da histeria para a teoria do inconsciente. Pergunte quais rupturas recebe destaque e quais dificuldades ficam menos visíveis.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"Uma autobiografia é ao mesmo tempo testemunho e construção narrativa. Use-a como ponte para documentos, não como autoridade histórica exclusiva."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “a narrativa de origem de freud”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Se um cientista descreve seu trabalho como sequência de descobertas inevitáveis, o historiador precisa examinar hesitações e revisões que ficaram fora desse relato.\n\nAgora retome o foco desta aula: a narrativa de origem de freud. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Autobiografia intelectual","desc":"Relato retrospectivo pelo próprio autor sobre formação e desenvolvimento de ideias."},{"term":"Historiografia","desc":"Trabalho crítico de reconstrução do passado mediante comparação de fontes."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “a narrativa de origem de freud” nesta obra?","options":["Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1925 [adendo de 1935], distinguindo hipótese, exemplos e limites da interpretação."],"correct":2,"feedback":"O tópico “A narrativa de origem de Freud” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1925 [adendo de 1935]) — Freud - Um Estudo Autobiográfico. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a127","title":"Freud - Um Estudo Autobiográfico #2","minutes":15,"hook":"Qual é o problema teórico por trás de “método, sonho e sexualidade” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “método, sonho e sexualidade”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Freud apresenta sua trajetória de pesquisa, as origens da técnica e o desenvolvimento da psicanálise. A autobiografia é fonte primária valiosa, mas também uma apresentação seletiva de si próprio; convém compará-la com correspondência, textos datados e historiografia."},{"title":"Entenda o conceito: Método, sonho e sexualidade","body":"Freud escolhe tópicos que considera centrais e articula suas descobertas numa história coerente. A ordem do relato autobiográfico não substitui a cronologia exata das publicações.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"Uma autobiografia é ao mesmo tempo testemunho e construção narrativa. Use-a como ponte para documentos, não como autoridade histórica exclusiva."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “método, sonho e sexualidade”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Se um cientista descreve seu trabalho como sequência de descobertas inevitáveis, o historiador precisa examinar hesitações e revisões que ficaram fora desse relato.\n\nAgora retome o foco desta aula: método, sonho e sexualidade. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Autobiografia intelectual","desc":"Relato retrospectivo pelo próprio autor sobre formação e desenvolvimento de ideias."},{"term":"Historiografia","desc":"Trabalho crítico de reconstrução do passado mediante comparação de fontes."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “método, sonho e sexualidade” nesta obra?","options":["Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1925 [adendo de 1935], distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal."],"correct":1,"feedback":"O tópico “Método, sonho e sexualidade” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1925 [adendo de 1935]) — Freud - Um Estudo Autobiográfico. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a128","title":"Freud - Um Estudo Autobiográfico #3","minutes":15,"hook":"Qual é o problema teórico por trás de “controvérsias e organização de um campo” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “controvérsias e organização de um campo”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Freud apresenta sua trajetória de pesquisa, as origens da técnica e o desenvolvimento da psicanálise. A autobiografia é fonte primária valiosa, mas também uma apresentação seletiva de si próprio; convém compará-la com correspondência, textos datados e historiografia."},{"title":"Entenda o conceito: Controvérsias e organização de um campo","body":"A maneira de narrar divergências mostra o esforço de delimitar a identidade da psicanálise. Histórias alternativas podem ressaltar outros protagonistas.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"Uma autobiografia é ao mesmo tempo testemunho e construção narrativa. Use-a como ponte para documentos, não como autoridade histórica exclusiva."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “controvérsias e organização de um campo”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Se um cientista descreve seu trabalho como sequência de descobertas inevitáveis, o historiador precisa examinar hesitações e revisões que ficaram fora desse relato.\n\nAgora retome o foco desta aula: controvérsias e organização de um campo. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Autobiografia intelectual","desc":"Relato retrospectivo pelo próprio autor sobre formação e desenvolvimento de ideias."},{"term":"Historiografia","desc":"Trabalho crítico de reconstrução do passado mediante comparação de fontes."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “controvérsias e organização de um campo” nesta obra?","options":["Examinar o argumento no contexto de 1925 [adendo de 1935], distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto."],"correct":0,"feedback":"O tópico “Controvérsias e organização de um campo” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1925 [adendo de 1935]) — Freud - Um Estudo Autobiográfico. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a129","title":"Freud - Um Estudo Autobiográfico #4","minutes":15,"hook":"Qual é o problema teórico por trás de “retrospecto e revisão” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “retrospecto e revisão”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Freud apresenta sua trajetória de pesquisa, as origens da técnica e o desenvolvimento da psicanálise. A autobiografia é fonte primária valiosa, mas também uma apresentação seletiva de si próprio; convém compará-la com correspondência, textos datados e historiografia."},{"title":"Entenda o conceito: Retrospecto e revisão","body":"O adendo escrito em 1935 permite comparar versões do percurso. Documentos autobiográficos também revelam como um autor quer que sua obra seja lida.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"Uma autobiografia é ao mesmo tempo testemunho e construção narrativa. Use-a como ponte para documentos, não como autoridade histórica exclusiva."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “retrospecto e revisão”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Se um cientista descreve seu trabalho como sequência de descobertas inevitáveis, o historiador precisa examinar hesitações e revisões que ficaram fora desse relato.\n\nAgora retome o foco desta aula: retrospecto e revisão. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Autobiografia intelectual","desc":"Relato retrospectivo pelo próprio autor sobre formação e desenvolvimento de ideias."},{"term":"Historiografia","desc":"Trabalho crítico de reconstrução do passado mediante comparação de fontes."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “retrospecto e revisão” nesta obra?","options":["Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1925 [adendo de 1935], distinguindo hipótese, exemplos e limites da interpretação."],"correct":2,"feedback":"O tópico “Retrospecto e revisão” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1925 [adendo de 1935]) — Freud - Um Estudo Autobiográfico. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a130","title":"Inibição, Sintomas e Ansiedade #1","minutes":18,"hook":"Qual é o problema teórico por trás de “inibição e sintoma: distinções necessárias” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “inibição e sintoma: distinções necessárias”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Na obra de 1926, frequentemente traduzida como Inibição, sintoma e angústia, Freud revisa aspectos da teoria da angústia e articula perigo, defesa e funcionamento do eu. A terminologia 'ansiedade' ou 'angústia' varia nas traduções, e convém preservar a referência ao termo Angst."},{"title":"Entenda o conceito: Inibição e sintoma: distinções necessárias","body":"Inibição envolve restrição de uma função, ao passo que sintoma se articula a formações de compromisso e conflitos. Nem toda dificuldade funcional indica um sintoma analítico específico.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"Compare a revisão de 1926 com as ideias anteriores e com a segunda tópica de 1923; termos parecidos podem operar em modelos distintos."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “inibição e sintoma: distinções necessárias”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Alguém deixa de falar em público por intenso medo. Pode haver inibição e sofrimento, mas isso não prova por si só uma fonte edípica específica. Uma avaliação cuidadosa é necessária.\n\nAgora retome o foco desta aula: inibição e sintoma: distinções necessárias. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Inibição","desc":"Restrição de função abordada por Freud, distinta de sintoma em sua elaboração de 1926."},{"term":"Angústia-sinal","desc":"Formulação do papel da angústia na resposta a situações de perigo."},{"term":"Desamparo","desc":"Conceito que Freud relaciona à dependência e a estados de perigo psíquico."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “inibição e sintoma: distinções necessárias” nesta obra?","options":["Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1926, distinguindo hipótese, exemplos e limites da interpretação."],"correct":2,"feedback":"O tópico “Inibição e sintoma: distinções necessárias” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1926) — Inibição, Sintomas e Ansiedade. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a131","title":"Inibição, Sintomas e Ansiedade #2","minutes":15,"hook":"Qual é o problema teórico por trás de “angústia-sinal e perigo” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “angústia-sinal e perigo”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Na obra de 1926, frequentemente traduzida como Inibição, sintoma e angústia, Freud revisa aspectos da teoria da angústia e articula perigo, defesa e funcionamento do eu. A terminologia 'ansiedade' ou 'angústia' varia nas traduções, e convém preservar a referência ao termo Angst."},{"title":"Entenda o conceito: Angústia-sinal e perigo","body":"Freud atribui ao eu um papel na produção de sinal diante de perigo, revendo concepções anteriores. O texto exige acompanhar alterações na relação entre defesa e angústia.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"Compare a revisão de 1926 com as ideias anteriores e com a segunda tópica de 1923; termos parecidos podem operar em modelos distintos."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “angústia-sinal e perigo”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Alguém deixa de falar em público por intenso medo. Pode haver inibição e sofrimento, mas isso não prova por si só uma fonte edípica específica. Uma avaliação cuidadosa é necessária.\n\nAgora retome o foco desta aula: angústia-sinal e perigo. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Inibição","desc":"Restrição de função abordada por Freud, distinta de sintoma em sua elaboração de 1926."},{"term":"Angústia-sinal","desc":"Formulação do papel da angústia na resposta a situações de perigo."},{"term":"Desamparo","desc":"Conceito que Freud relaciona à dependência e a estados de perigo psíquico."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “angústia-sinal e perigo” nesta obra?","options":["Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1926, distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal."],"correct":1,"feedback":"O tópico “Angústia-sinal e perigo” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1926) — Inibição, Sintomas e Ansiedade. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a132","title":"Inibição, Sintomas e Ansiedade #3","minutes":15,"hook":"Qual é o problema teórico por trás de “desamparo e reformulação teórica” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “desamparo e reformulação teórica”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Na obra de 1926, frequentemente traduzida como Inibição, sintoma e angústia, Freud revisa aspectos da teoria da angústia e articula perigo, defesa e funcionamento do eu. A terminologia 'ansiedade' ou 'angústia' varia nas traduções, e convém preservar a referência ao termo Angst."},{"title":"Entenda o conceito: Desamparo e reformulação teórica","body":"A questão do desamparo e das perdas possíveis aparece ligada à teoria do perigo. Estude com cautela as relações com separação, castração e modelos da época.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"Compare a revisão de 1926 com as ideias anteriores e com a segunda tópica de 1923; termos parecidos podem operar em modelos distintos."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “desamparo e reformulação teórica”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Alguém deixa de falar em público por intenso medo. Pode haver inibição e sofrimento, mas isso não prova por si só uma fonte edípica específica. Uma avaliação cuidadosa é necessária.\n\nAgora retome o foco desta aula: desamparo e reformulação teórica. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Inibição","desc":"Restrição de função abordada por Freud, distinta de sintoma em sua elaboração de 1926."},{"term":"Angústia-sinal","desc":"Formulação do papel da angústia na resposta a situações de perigo."},{"term":"Desamparo","desc":"Conceito que Freud relaciona à dependência e a estados de perigo psíquico."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “desamparo e reformulação teórica” nesta obra?","options":["Examinar o argumento no contexto de 1926, distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto."],"correct":0,"feedback":"O tópico “Desamparo e reformulação teórica” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1926) — Inibição, Sintomas e Ansiedade. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a133","title":"A Questão da Análise Leiga #1","minutes":18,"hook":"Qual é o problema teórico por trás de “por que freud defende uma formação não exclusivamente médica?” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “por que freud defende uma formação não exclusivamente médica?”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Freud debate se a psicanálise deveria ser praticada exclusivamente por médicos. A discussão envolve formação, saber técnico, ética e fronteiras profissionais. Os argumentos históricos não substituem a legislação vigente em cada país e as regras de proteção de pacientes."},{"title":"Entenda o conceito: Por que Freud defende uma formação não exclusivamente médica?","body":"O autor argumenta que o método exige conhecimentos e experiência que não se resumem ao diploma em medicina. Isso não significa dispensar capacitação ou ignorar sofrimento físico e psiquiátrico.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"Essa discussão aproxima estudo histórico de profissão contemporânea, exigindo consultar as regras da jurisdição relevante."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “por que freud defende uma formação não exclusivamente médica?”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Uma pessoa sem formação clínica quer iniciar atendimentos com base na leitura do livro. A defesa freudiana da análise leiga não torna suficiente uma leitura isolada nem elimina obrigações legais e éticas.\n\nAgora retome o foco desta aula: por que freud defende uma formação não exclusivamente médica?. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Análise leiga","desc":"Expressão histórica para o exercício da psicanálise por profissionais que não são médicos."},{"term":"Responsabilidade profissional","desc":"Conjunto de deveres de competência, sigilo, proteção e observância de regras aplicáveis."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “por que freud defende uma formação não exclusivamente médica?” nesta obra?","options":["Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1926, distinguindo hipótese, exemplos e limites da interpretação."],"correct":2,"feedback":"O tópico “Por que Freud defende uma formação não exclusivamente médica?” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1926) — A Questão da Análise Leiga. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a134","title":"A Questão da Análise Leiga #2","minutes":15,"hook":"Qual é o problema teórico por trás de “o lugar da formação teórica e clínica” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “o lugar da formação teórica e clínica”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Freud debate se a psicanálise deveria ser praticada exclusivamente por médicos. A discussão envolve formação, saber técnico, ética e fronteiras profissionais. Os argumentos históricos não substituem a legislação vigente em cada país e as regras de proteção de pacientes."},{"title":"Entenda o conceito: O lugar da formação teórica e clínica","body":"Freud discute a necessidade de estudar o inconsciente, a sexualidade, as defesas e as ciências humanas. Uma formação adequada inclui reconhecer os limites do próprio campo.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"Essa discussão aproxima estudo histórico de profissão contemporânea, exigindo consultar as regras da jurisdição relevante."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “o lugar da formação teórica e clínica”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Uma pessoa sem formação clínica quer iniciar atendimentos com base na leitura do livro. A defesa freudiana da análise leiga não torna suficiente uma leitura isolada nem elimina obrigações legais e éticas.\n\nAgora retome o foco desta aula: o lugar da formação teórica e clínica. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Análise leiga","desc":"Expressão histórica para o exercício da psicanálise por profissionais que não são médicos."},{"term":"Responsabilidade profissional","desc":"Conjunto de deveres de competência, sigilo, proteção e observância de regras aplicáveis."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “o lugar da formação teórica e clínica” nesta obra?","options":["Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1926, distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal."],"correct":1,"feedback":"O tópico “O lugar da formação teórica e clínica” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1926) — A Questão da Análise Leiga. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a135","title":"A Questão da Análise Leiga #3","minutes":15,"hook":"Qual é o problema teórico por trás de “ética, regulação e responsabilidade atuais” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “ética, regulação e responsabilidade atuais”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Freud debate se a psicanálise deveria ser praticada exclusivamente por médicos. A discussão envolve formação, saber técnico, ética e fronteiras profissionais. Os argumentos históricos não substituem a legislação vigente em cada país e as regras de proteção de pacientes."},{"title":"Entenda o conceito: Ética, regulação e responsabilidade atuais","body":"Perguntas sobre autorização de exercício profissional dependem de legislação e credenciais específicas. O texto de 1926 não deve ser usado como permissão universal para atuar sem requisitos locais.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"Essa discussão aproxima estudo histórico de profissão contemporânea, exigindo consultar as regras da jurisdição relevante."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “ética, regulação e responsabilidade atuais”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Uma pessoa sem formação clínica quer iniciar atendimentos com base na leitura do livro. A defesa freudiana da análise leiga não torna suficiente uma leitura isolada nem elimina obrigações legais e éticas.\n\nAgora retome o foco desta aula: ética, regulação e responsabilidade atuais. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Análise leiga","desc":"Expressão histórica para o exercício da psicanálise por profissionais que não são médicos."},{"term":"Responsabilidade profissional","desc":"Conjunto de deveres de competência, sigilo, proteção e observância de regras aplicáveis."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “ética, regulação e responsabilidade atuais” nesta obra?","options":["Examinar o argumento no contexto de 1926, distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto."],"correct":0,"feedback":"O tópico “Ética, regulação e responsabilidade atuais” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1926) — A Questão da Análise Leiga. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a136","title":"O Futuro de uma Ilusão","minutes":18,"hook":"Qual é o problema teórico por trás de “ilusão, desejo e crítica cultural” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “ilusão, desejo e crítica cultural”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Freud examina crenças religiosas como fenômenos culturais e psíquicos, associando-as à questão do desamparo e da busca de proteção. A tese é uma interpretação freudiana da religião, não uma demonstração de que toda experiência religiosa seja doença, falsidade ou imaturidade."},{"title":"Entenda o conceito: Ilusão, desejo e crítica cultural","body":"No uso freudiano, ilusão diz respeito ao papel do desejo na sustentação de uma crença; não se define simplesmente pela falsidade comprovada. Uma leitura responsável diferencia crítica de instituições, hipótese psicológica e respeito às escolhas religiosas das pessoas.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"Conecte com Totem e tabu e O mal-estar na civilização, reconhecendo que religião tem dimensões históricas e sociais não reduzíveis à psicologia individual."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “ilusão, desejo e crítica cultural”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Um analisando encontra apoio em sua espiritualidade. Não há razão clínica para atacar sua crença a partir do ensaio de Freud; pode-se investigar de que modo ela participa de sua vida, quando isso é relevante.\n\nAgora retome o foco desta aula: ilusão, desejo e crítica cultural. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Ilusão","desc":"No texto freudiano, crença cuja motivação é relacionada a desejo; não significa sinônimo simples de erro factual."},{"term":"Desamparo","desc":"Condição de vulnerabilidade abordada por Freud como parte da experiência humana."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “ilusão, desejo e crítica cultural” nesta obra?","options":["Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1927, distinguindo hipótese, exemplos e limites da interpretação."],"correct":2,"feedback":"O tópico “Ilusão, desejo e crítica cultural” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1927) — O Futuro de uma Ilusão. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a137","title":"O Mal Estar na Civilização","minutes":18,"hook":"Qual é o problema teórico por trás de “cultura, laço social e mal-estar” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “cultura, laço social e mal-estar”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"A obra discute tensões entre exigências culturais, agressividade, sofrimento, trabalho, vínculos e renúncia pulsional. Freud não apresenta uma teoria sociológica total; constrói hipóteses psicanalíticas sobre a convivência humana e o conflito entre satisfação e restrição. A análise deve preservar diferenças de classe, gênero, raça e contexto histórico, pouco contempladas em suas generalizações."},{"title":"Entenda o conceito: Cultura, laço social e mal-estar","body":"Freud pergunta por que a vida coletiva oferece proteção e ao mesmo tempo cobra renúncias. A culpa e o supereu participam de sua explicação, mas o sofrimento social não pode ser reduzido à economia pulsional de um indivíduo.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"Relacione com Psicologia das massas, Futuro de uma ilusão e textos sobre supereu e agressividade."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “cultura, laço social e mal-estar”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"A exaustão de alguém num trabalho precarizado não pode ser explicada apenas pela renúncia pulsional. Condições materiais são indispensáveis à compreensão do sofrimento.\n\nAgora retome o foco desta aula: cultura, laço social e mal-estar. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Civilização/cultura","desc":"Termos usados na tradução de Kultur em uma reflexão sobre vida coletiva."},{"term":"Mal-estar","desc":"Tensão teorizada por Freud entre exigências sociais, desejos e conflitos."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “cultura, laço social e mal-estar” nesta obra?","options":["Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1930, distinguindo hipótese, exemplos e limites da interpretação."],"correct":2,"feedback":"O tópico “Cultura, laço social e mal-estar” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1930) — O Mal Estar na Civilização. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a138","title":"Algumas Consequências Psíquicas das Diferenças Anatômicas #1","minutes":18,"hook":"Qual é o problema teórico por trás de “diferença anatômica e sua interpretação psíquica” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “diferença anatômica e sua interpretação psíquica”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"O texto de 1925 apresenta hipóteses de Freud sobre diferenças sexuais, castração e desenvolvimento, apoiadas em parâmetros binários e hierarquizantes. É fundamental distinguir o valor histórico do debate de afirmações que hoje não devem servir à patologização de mulheres, pessoas trans ou intersexo."},{"title":"Entenda o conceito: Diferença anatômica e sua interpretação psíquica","body":"Freud discute como a percepção de diferenças corporais pode ser simbolizada e vivida. Isso não torna anatomia destino nem prova que pessoas com corpos semelhantes tenham a mesma experiência subjetiva.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"Compare com textos de Horney e debates posteriores sobre feminilidade e cultura. Não confunda anatomia, sexo, gênero, identidade e desejo.\n\nNota crítica: descrições históricas sobre gênero não são critérios contemporâneos de normalidade."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “diferença anatômica e sua interpretação psíquica”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Uma pessoa trans descreve sua experiência de gênero. A teoria de 1925 não autoriza enquadrá-la em deficiência psíquica ou num destino anatômico supostamente necessário.\n\nAgora retome o foco desta aula: diferença anatômica e sua interpretação psíquica. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Diferença sexual","desc":"Questão teórica complexa que não se reduz automaticamente à anatomia."},{"term":"Anatomia e destino","desc":"Problema histórico de como teorias ligaram corpo e desenvolvimento psíquico."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “diferença anatômica e sua interpretação psíquica” nesta obra?","options":["Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1925, distinguindo hipótese, exemplos e limites da interpretação."],"correct":2,"feedback":"O tópico “Diferença anatômica e sua interpretação psíquica” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1925) — Algumas Consequências Psíquicas das Diferenças Anatômicas. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a139","title":"Algumas Consequências Psíquicas das Diferenças Anatômicas #2","minutes":15,"hook":"Qual é o problema teórico por trás de “limites e críticas às hipóteses freudianas” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “limites e críticas às hipóteses freudianas”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"O texto de 1925 apresenta hipóteses de Freud sobre diferenças sexuais, castração e desenvolvimento, apoiadas em parâmetros binários e hierarquizantes. É fundamental distinguir o valor histórico do debate de afirmações que hoje não devem servir à patologização de mulheres, pessoas trans ou intersexo."},{"title":"Entenda o conceito: Limites e críticas às hipóteses freudianas","body":"A obra motivou debates posteriores, inclusive de psicanalistas mulheres. Estude objeções aos pressupostos de falta, inveja e hierarquização sem converter uma teoria datada em prescrição clínica.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"Compare com textos de Horney e debates posteriores sobre feminilidade e cultura. Não confunda anatomia, sexo, gênero, identidade e desejo.\n\nNota crítica: descrições históricas sobre gênero não são critérios contemporâneos de normalidade."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “limites e críticas às hipóteses freudianas”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Uma pessoa trans descreve sua experiência de gênero. A teoria de 1925 não autoriza enquadrá-la em deficiência psíquica ou num destino anatômico supostamente necessário.\n\nAgora retome o foco desta aula: limites e críticas às hipóteses freudianas. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Diferença sexual","desc":"Questão teórica complexa que não se reduz automaticamente à anatomia."},{"term":"Anatomia e destino","desc":"Problema histórico de como teorias ligaram corpo e desenvolvimento psíquico."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “limites e críticas às hipóteses freudianas” nesta obra?","options":["Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1925, distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal."],"correct":1,"feedback":"O tópico “Limites e críticas às hipóteses freudianas” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1925) — Algumas Consequências Psíquicas das Diferenças Anatômicas. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a140","title":"Sexualidade Feminina #1","minutes":18,"hook":"Qual é o problema teórico por trás de “relações precoces e vínculos com cuidadores” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “relações precoces e vínculos com cuidadores”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Em 1931 Freud volta a formular hipóteses sobre vínculos precoces, sexualidade e desenvolvimento de meninas. Sua descrição parte de papéis de gênero e posições familiares específicos, contestados por autoras posteriores. O texto é relevante para a história das controvérsias, não como explicação universal da experiência de mulheres."},{"title":"Entenda o conceito: Relações precoces e vínculos com cuidadores","body":"Freud enfatiza a importância de vínculos iniciais e das mudanças em suas direções. A pergunta pode enriquecer estudos sobre desenvolvimento, mas não autoriza supor que toda pessoa siga a mesma trajetória.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"Relacione com Algumas consequências psíquicas das diferenças anatômicas, Complexo de Édipo e debates de Karen Horney, sem homogeneizar mulheres."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “relações precoces e vínculos com cuidadores”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Duas mulheres relatam histórias familiares e afetivas distintas. Nenhuma deve ser considerada menos feminina por não reproduzir uma sequência postulada em 1931.\n\nAgora retome o foco desta aula: relações precoces e vínculos com cuidadores. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Feminilidade (Freud)","desc":"Categoria teórica historicamente situada, que não deve ser tratada como essência natural."},{"term":"Vínculos precoces","desc":"Relações iniciais com cuidadores, estudadas por diferentes tradições psicanalíticas."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “relações precoces e vínculos com cuidadores” nesta obra?","options":["Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1931, distinguindo hipótese, exemplos e limites da interpretação."],"correct":2,"feedback":"O tópico “Relações precoces e vínculos com cuidadores” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1931) — Sexualidade Feminina. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a141","title":"Sexualidade Feminina #2","minutes":15,"hook":"Qual é o problema teórico por trás de “crítica à universalização da feminilidade” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “crítica à universalização da feminilidade”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Em 1931 Freud volta a formular hipóteses sobre vínculos precoces, sexualidade e desenvolvimento de meninas. Sua descrição parte de papéis de gênero e posições familiares específicos, contestados por autoras posteriores. O texto é relevante para a história das controvérsias, não como explicação universal da experiência de mulheres."},{"title":"Entenda o conceito: Crítica à universalização da feminilidade","body":"Os conceitos de 'feminino' do período misturam hipóteses psíquicas com expectativas culturais. Confrontar o texto com críticas posteriores torna-se parte da própria aprendizagem.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"Relacione com Algumas consequências psíquicas das diferenças anatômicas, Complexo de Édipo e debates de Karen Horney, sem homogeneizar mulheres."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “crítica à universalização da feminilidade”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Duas mulheres relatam histórias familiares e afetivas distintas. Nenhuma deve ser considerada menos feminina por não reproduzir uma sequência postulada em 1931.\n\nAgora retome o foco desta aula: crítica à universalização da feminilidade. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Feminilidade (Freud)","desc":"Categoria teórica historicamente situada, que não deve ser tratada como essência natural."},{"term":"Vínculos precoces","desc":"Relações iniciais com cuidadores, estudadas por diferentes tradições psicanalíticas."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “crítica à universalização da feminilidade” nesta obra?","options":["Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1931, distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal."],"correct":1,"feedback":"O tópico “Crítica à universalização da feminilidade” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1931) — Sexualidade Feminina. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a142","title":"Tipos libidinais #1","minutes":18,"hook":"Qual é o problema teórico por trás de “tipos erótico, obsessivo e narcísico” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “tipos erótico, obsessivo e narcísico”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Freud propõe uma classificação exploratória de tipos libidinais, distinguindo ênfases de investimento. O texto é breve e especulativo; os 'tipos' não são diagnósticos modernos, testes de personalidade nem identidades fixas."},{"title":"Entenda o conceito: Tipos erótico, obsessivo e narcísico","body":"A proposta discrimina tendências em torno de amor, exigência e investimento no eu, entre outras articulações. É uma ferramenta de descrição histórica e não rótulo para decidir quem alguém 'é'.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"Compare o texto de 1931 com Sobre o narcisismo (1914) e com a segunda tópica, observando mudança de funções conceituais."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “tipos erótico, obsessivo e narcísico”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Classificar um conhecido como 'tipo narcísico' a partir de duas frases seria extrapolação. Uma tipologia histórica não substitui avaliação individual.\n\nAgora retome o foco desta aula: tipos erótico, obsessivo e narcísico. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Tipo libidinal","desc":"Categoria exploratória usada por Freud em 1931 para descrever certas orientações de investimento."},{"term":"Tipo narcísico","desc":"Uma das categorias históricas de Freud, distinta de diagnóstico de transtorno."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “tipos erótico, obsessivo e narcísico” nesta obra?","options":["Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1931, distinguindo hipótese, exemplos e limites da interpretação."],"correct":2,"feedback":"O tópico “Tipos erótico, obsessivo e narcísico” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1931) — Tipos libidinais. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a143","title":"Tipos libidinais #2","minutes":15,"hook":"Qual é o problema teórico por trás de “misturas e limites das tipologias” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “misturas e limites das tipologias”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Freud propõe uma classificação exploratória de tipos libidinais, distinguindo ênfases de investimento. O texto é breve e especulativo; os 'tipos' não são diagnósticos modernos, testes de personalidade nem identidades fixas."},{"title":"Entenda o conceito: Misturas e limites das tipologias","body":"O próprio recurso aos tipos exige reconhecer variações e combinações. O estudo deve perguntar o que as categorias iluminam e o que deixam de fora.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"Compare o texto de 1931 com Sobre o narcisismo (1914) e com a segunda tópica, observando mudança de funções conceituais."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “misturas e limites das tipologias”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Classificar um conhecido como 'tipo narcísico' a partir de duas frases seria extrapolação. Uma tipologia histórica não substitui avaliação individual.\n\nAgora retome o foco desta aula: misturas e limites das tipologias. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Tipo libidinal","desc":"Categoria exploratória usada por Freud em 1931 para descrever certas orientações de investimento."},{"term":"Tipo narcísico","desc":"Uma das categorias históricas de Freud, distinta de diagnóstico de transtorno."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “misturas e limites das tipologias” nesta obra?","options":["Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1931, distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal."],"correct":1,"feedback":"O tópico “Misturas e limites das tipologias” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1931) — Tipos libidinais. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]}]});
